#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    char *name;
    int score;
    struct Node *next;
} Node;

Node *add_last(Node *head, char *name, int score) {
    Node *fresh = malloc(sizeof(Node));
    if (fresh == NULL) {
        return head;
    }
    fresh->name = name;
    fresh->score = score;
    fresh->next = NULL;
    if (head == NULL) {
        return fresh;
    }
    Node *p = head;
    while (p->next != NULL) {
        p = p->next;
    }
    p->next = fresh;
    return head;
}

void save_to_file(Node *head, const char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        printf("档案开不了喵\n");
        return;
    }
    for (Node *p = head; p != NULL; p = p->next) {
        fprintf(fp, "%s %d\n", p->name, p->score);
    }
    fclose(fp);
}

int main(void) {
    Node *head = NULL;
    head = add_last(head, "{n1}", {s1});
    head = add_last(head, "{n2}", {s2});
    head = add_last(head, "{n3}", {s3});
    save_to_file(head, "scores.txt");

    FILE *fp = fopen("scores.txt", "r");
    if (fp == NULL) {
        printf("档案丢了喵\n");
        return 0;
    }
